#!/usr/bin/env node
'use strict';

const fs = require('fs');
const path = require('path');

const projectRoot = path.join(__dirname, '..');
const sourceFiles = [
  'src/shared/constants.js',
  'src/shared/log.js',
  'src/shared/url.js',
  'src/shared/storage.js',
  'src/shared/discovery-storage.js',
  'src/shared/messages.js',
  'src/shared/markdown.js',
  'src/shared/dates.js',
  'src/content/field-registry.js',
  'src/content/extractors.js',
  'src/content/section-expander.js',
  'src/content/original-description-enhancer.js',
  'src/content/ui.js',
  'src/content/navigation.js',
  'src/content/controller.js',
  'src/content/index.js'
];
const outputFile = path.join(projectRoot, 'src', 'content', 'content-script.bundle.js');

const bundle = [
  '/* Generated by scripts/build-content-bundle.js.',
  ' * Source order is significant; update the sourceFiles list if the manifest boot order changes.',
  ' */',
  ''
].concat(
  sourceFiles.map((relativePath) => {
    const absolutePath = path.join(projectRoot, relativePath);
    return [
      `/* ${relativePath} */`,
      fs.readFileSync(absolutePath, 'utf8').trimEnd(),
      ''
    ].join('\n');
  })
).join('\n');

fs.writeFileSync(outputFile, `${bundle}\n`);
